/**
 * Meridian Werks’ Build plan case page (spec 2026-10-05 per-site pages): the
 * blueprint behind the three flows on its Automation page, MW-01 on Zapier,
 * MW-02 on n8n and MW-03 on Make, with the helpers, data, tests and handover
 * they need. MW-01 is the general page’s Service booking, given depth.
 * data/cases/index.ts registers it; `npm run cases` renders it into
 * public/cases/meridian-werks/build-plan.html. Only type imports, so Node can
 * run it directly.
 */
import type { IconName, NodeKind, Plan, PlanEdge, PlanNode, Workflow } from '../../buildPlan.ts'
import type { ToolId } from '../../../lib/brand/tools.ts'

const node = (id: string, kind: NodeKind, label: string, sub: string, icon: IconName, tools: ToolId[], type: string, settings: [string, string][], what: string): PlanNode =>
  ({ id, kind, label, sub, icon, type, settings, what, tools })
const edge = (from: string, to: string, label?: string): PlanEdge => (label ? { from, to, label } : { from, to })

/** Who says yes, as on the Automation page. */
const YES = 'Ilse Brandt, the workshop manager, confirms every booking by phone, prices every estimate, checks every health report before it reaches the owner’s inbox, and checks every fleet report before it reaches the client. Anton Vosloo signs off every pre-purchase inspection, every performance refinement and every finding that is calibration work before its report goes. The owner’s yes, on the answer form or by phone to Ilse, is what starts the work, and a variation needs a new one. The booking receipt, the workshop messages and the fleet report email are fixed templates: the receipt and the messages send on their own, and the fleet report email only once Ilse has checked the report. In these flows Claude drafts only the plain-language summary in a health report, rewording what the technician recorded, and it never diagnoses.'

/** Personal data, as every flow treats it. */
const DATA = 'A registration number is personal data. It is kept on the job card, and never in a Telegram message, an email subject, a fleet report, a log such as the Failed runs tab, or anything Claude reads. Zapier’s run history holds the booking form’s payload, as it holds every run’s data. The owner’s name, email and phone stay on the job card too, and messages link to the card instead. Amounts are in euros.'

